from pathlib import Path
import json
r=Path(__file__).parent;d=json.loads((r/'raw.json').read_text());e=json.loads((r/'exit.json').read_text());c=json.loads((r/'cleanup.json').read_text());pairs=[{'label':a['message'],'nativeFrameToken':a['frameToken'],'cdpFrameId':b['params']['frameId'],'same':a['frameToken']==b['params']['frameId']}for a,b in zip(d['dialogs'],d['opened'])]
checks={'actual9Pairs':len(pairs)==9 and len(d['closed'])==9,'allTokensDifferent':all(not x['same'] for x in pairs),'mainFrameNativeAndCdpEachStable':len({x['nativeFrameToken']for x in pairs[:7]})==len({x['cdpFrameId']for x in pairs[:7]})==1,'threeDistinctNativeFrames':len({x['nativeFrameToken']for x in pairs})==3,'threeDistinctCdpFrames':len({x['cdpFrameId']for x in pairs})==3,'noRuntimeErrors':not d['errors'] and not d.get('error'),'normalExitAndRestore':e['code']==0 and not e['signals'] and d['handlerRestored'] and d['serverClosed'],'exactCleanup':c['allExactPidsAbsent'] and c['portClosed']}
out={'classification':'frame-token-equals-cdp-id-assumption-disproved' if all(checks.values()) else 'needs-review','checks':checks,'pairs':pairs,'formalIncrement':0,'boundary':'New identity-correlation question only. Prior callback green not expanded into production, Helper, App UI or original case claim. Native frameToken must never be used as CDP frameId.'};(r/'adjudication.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'classification':out['classification'],'checks':checks},ensure_ascii=False))
